import{z as B,x as A,o as t,c as p,q as s,j as l,D as e,d as n,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"类型健全性","description":"","frontmatter":{"title":"类型健全性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/type-soundness.md","filePath":"cs/type-soundness.md","lastUpdated":1791063341000}'),d={name:"cs/type-soundness.md"};function c(h,a,u,m,F,D){const r=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=s('<h1 id="类型健全性" tabindex="-1">类型健全性 <a class="header-anchor" href="#类型健全性" aria-label="Permalink to &quot;类型健全性&quot;">​</a></h1><div class="epigraph"><p>进展：良型项不是卡住的非值。保持：一步归约仍良型。合起来：良型程序不会达到「无法再走且不是值」的状态。</p><footer>—— 据 Wright and Felleisen, A Syntactic Approach to Type Soundness, 1994；Pierce TAPL 第 8 章；Milner, 1978 整理</footer></div><p>上一课<a href="/cs/gradual-typing">渐进类型</a>靠运行时强制补洞。缺口是把本单元各系统的承诺收成<strong>定理形状</strong>：健全性。主干类型检查课是算法；本课是「算法在证明什么」。不重推 STLC 全部规则，只钉进展+保持，以及失败模式（未定义行为、<code>unsafe</code>、不健全渐进）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「不会出错」含糊。Wright–Felleisen：在操作语义上证。卡住：非值且无规则可应用（对 STLC 而言如把整数当函数用）。良型排除卡住。缺口是<strong>这两个引理</strong>，不是词法。</p><p>反例：C 的类型系统对缓冲区越界不承诺；Java 对 <code>null</code> 有例外——可把例外当定义的归约，仍「健全」但有陷阱。后课 Option 专门收空。</p><p><span class="marginnote">「卡住状态」就是程序走到既不是值、又没有任何归约规则能往下走的那一步——比如把整数 3 当函数调用。进展引理保证：良型程序永远到不了这一步。</span></p><h3 id="健全不是完备" tabindex="-1">健全不是完备 <a class="header-anchor" href="#健全不是完备" aria-label="Permalink to &quot;健全不是完备&quot;">​</a></h3><p>健全：能型则行为遵守。完备：该能型的都能型。HM 对核心 Mini-ML 有主类型；加特设重载后常不完备。不要把二者当一句。</p><p><span class="marginnote">Wright–Felleisen 1994。Milner 的「well-typed programs cannot go wrong」。Pierce TAPL 把进展保持当标准作业。本课不证强规范化（STLC 另有），只点名它更强。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先定值与一步 \\(\\to\\)。证保持：对推导归纳。证进展：对推导归纳，应用情形用保持保证左件是 λ。加引用后须加存储分型。加并发须改「出错」定义（数据竞争可在模型里当未定义）。</p>',12)),(t(),l(i,null,{default:e(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20WT%5B%22%CE%93%20%E2%8A%A2%20t%20%3A%20%CF%84%22%5D%20--%3E%20PRG%5B%22%E8%BF%9B%E5%B1%95%EF%BC%9A%E5%8F%AF%E8%B5%B0%E6%88%96%E4%B8%BA%E5%80%BC%22%5D%0A%20%20WT%20--%3E%20PRE%5B%22%E4%BF%9D%E6%8C%81%EF%BC%9A%E4%B8%80%E6%AD%A5%E4%BB%8D%E8%89%AF%E5%9E%8B%22%5D%0A%20%20PRG%20--%3E%20SF%5B%22%E4%B8%8D%E5%8D%A1%E4%BD%8F%22%5D%0A%20%20PRE%20--%3E%20SF%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与线性、借用：进展的「值」包含「不能再使用已移动的变量」——那些程序根本不井型。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"健全性定理要先钉死「什么叫错」——同一程序在两种语义下命运完全不同：",-1)),(t(),l(i,null,{default:e(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E6%BA%90%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20SEM%7B%22%E8%AF%AD%E4%B9%89%E6%80%8E%E4%B9%88%E5%AE%9A%E4%B9%89%E5%87%BA%E9%94%99%22%7D%0A%20%20SEM%20--%3E%7C%22%E6%8A%8A%E5%8D%A1%E4%BD%8F%E5%BD%93%E5%87%BA%E9%94%99%22%7C%20THM%5B%22%E5%8F%AF%E8%AF%81%E8%BF%9B%E5%B1%95%2B%E4%BF%9D%E6%8C%81%22%5D%0A%20%20THM%20--%3E%20SAFE%5B%22%E8%89%AF%E5%9E%8B%E7%A8%8B%E5%BA%8F%E4%B8%8D%E4%BC%9A%E5%8D%A1%E4%BD%8F%22%5D%0A%20%20SEM%20--%3E%7C%22%E6%8A%8A%E8%B6%8A%E7%95%8C%E5%BD%93%E4%BB%BB%E6%84%8F%E8%A1%8C%E4%B8%BA%22%7C%20HOLE%5B%22%E5%AE%9A%E7%90%86%E5%87%BA%E7%8E%B0%E7%A9%BA%E6%B4%9E%22%5D%0A%20%20HOLE%20--%3E%20ANY%5B%22%E4%BC%98%E5%8C%96%E5%8F%AF%E6%8A%8A%E7%A8%8B%E5%BA%8F%E5%8F%98%E6%88%90%E4%BB%BB%E4%BD%95%E4%B8%9C%E8%A5%BF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">直觉类比：进展与保持像两条棋规——进展说「轮到你时，要么已赢、要么有合法一步」；保持说「走一步之后棋局仍然合法」。两条合起来，永远不会出现「既不能走又没输」的死局。</span></p><p>语义里若把越界当任意行为（C UB），则没有「卡住」可证，优化可把井型源程序变成任何东西——<a href="/cs/undefined-behavior-opt">未定义行为与优化</a> 再展开。健全性定理必须先钉语言的对错状态。</p><p>渐进：强制失败是定义的归约（blame），仍可健全。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写并发内存模型全文。后课默认：健全 = 进展+保持（相对给定语义）。下一课把语义本身讲清：操作语义。</p><p>也不把测试覆盖当健全性证明。</p><p><span class="marginnote">常见误区：初学者容易以为「类型通过 = 程序没有 bug」。健全性只承诺不发生类型层面的卡住；空指针、死循环若被编进语义的例外里仍会发生——区别只是行为有定义，而不是不会出现。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进展+保持 ⇒ 良型不卡住（相对所选语义）。</li><li>例外可编进语义；UB 则定理空洞。</li><li>健全≠完备。</li><li>出处：Wright and Felleisen, 1994；Pierce TAPL；Milner, 1978。</li></ul>',9))])}const T=B(d,[["render",c]]);export{f as __pageData,T as default};
